def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.38
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.72
        return float(max(0.0, min(budget, base)))

    highest_prev = 0.0
    cindy_prev = None
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        if float(opp.get('budget', 0.0)) >= DAILY_SALARY * 4:
            rich_opp += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0.0)) <= 2:
            urgent_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid_val = float(bid)
            if bid_val > highest_prev:
                highest_prev = bid_val
        if opp_id == 'Cindy':
            if bid is not None:
                cindy_prev = float(bid)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 1:
        danger += 0.75
    elif hp <= 3:
        danger += 0.45
    if no_water >= 2:
        danger += 0.8
    elif no_water >= 1:
        danger += 0.35

    base = DAILY_SALARY * (0.34 + 0.22 * scarcity + 0.28 * min(1.0, danger))

    if highest_prev > 0:
        if highest_prev >= 140:
            react = DAILY_SALARY * (0.42 + 0.18 * scarcity)
            if danger >= 0.45:
                react = DAILY_SALARY * (0.82 + 0.08 * scarcity)
        elif highest_prev >= 90:
            react = min(highest_prev + 2.0, DAILY_SALARY * 0.96)
            if hp > 4 and no_water == 0 and supply >= 20:
                react = DAILY_SALARY * 0.46
        else:
            react = max(base, highest_prev + 1.5)
    else:
        react = base

    if cindy_prev is not None and cindy_prev >= 150 and hp > 3 and no_water == 0:
        react = min(react, DAILY_SALARY * (0.40 + 0.10 * scarcity))

    if urgent_opp >= 2 and hp > 3 and no_water == 0:
        react *= 0.92
    if rich_opp >= 2 and (hp <= 3 or no_water >= 1):
        react = max(react, DAILY_SALARY * 0.88)

    if supply <= 16:
        react += 6.0
    elif supply >= 23 and hp > 3 and no_water == 0:
        react -= 4.0

    if day >= 8:
        if hp <= 3 or no_water >= 1:
            react = max(react, DAILY_SALARY * 0.9)
        else:
            react = max(react, DAILY_SALARY * 0.5)

    if budget < DAILY_SALARY * 1.2:
        react = min(react, budget * 0.72 + 4.0)
    elif budget > DAILY_SALARY * 6:
        react = min(react + 3.0, budget)

    bid = max(0.0, min(budget, react))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False) and o.get('hp', 0) > -999:
            alive.append((oid, o))

    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids for immediate reaction
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate how contested the market was
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: higher supply reduces urgency to overbid
    # Map supply in [15,25] to a risk factor in [1.0,0.6]
    if MAX_SUPPLY > MIN_SUPPLY:
        risk = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
    else:
        risk = 1.0

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # If our HP is critical, bid to secure water regardless of others
    if my_hp <= 2.0:
        target = DAILY_SALARY * (0.85 * risk)
        return float(min(my_budget, target))

    # If others were very aggressive yesterday, slightly raise to avoid being outbid
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # We can afford moderate pressure; don't match extreme bids
        target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.55) * risk
        return float(min(my_budget, target))

    # Otherwise, bid conservatively but enough to compete in medium scenario
    # Base depends on supply: lower supply -> higher bid
    base = DAILY_SALARY * (0.42 + 0.18 * (1.0 - ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)))) if MAX_SUPPLY > MIN_SUPPLY else DAILY_SALARY * 0.5
    # Also scale down as our HP is healthy
    hp_scale = 0.95 if my_hp >= 7.0 else (0.75 if my_hp >= 4.0 else 0.9)
    target = base * hp_scale * risk
    return float(min(my_budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = 0.0
    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 7:
        base_bid = DAILY_SALARY * 0.7
    else:
        base_bid = DAILY_SALARY * 0.6

    calculated_bid = base_bid
    if highest_prev_bid > 0.0:
        if my_status['hp'] <= 2:
            calculated_bid = max(base_bid, highest_prev_bid + 5.0)
        elif my_status['hp'] <= 4:
            calculated_bid = max(base_bid, highest_prev_bid + 3.0)
        elif my_status['hp'] <= 7:
            calculated_bid = max(base_bid, highest_prev_bid + 1.5)
        else:
            calculated_bid = max(base_bid, highest_prev_bid + 0.5)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        calculated_bid = max(calculated_bid, DAILY_SALARY * 0.98)
    elif remaining_days <= 4:
        calculated_bid = max(calculated_bid, DAILY_SALARY * 0.9)

    final_bid = min(my_status['budget'], calculated_bid)

    if my_status['budget'] >= 1.0 and final_bid < 1.0:
        final_bid = 1.0
    elif my_status['budget'] == 0:
        final_bid = 0.0

    return final_bid

